internal sealed class NativeOrdinaryAcquisitionProbe{internal static NativeOrdinaryAcquisitionProbe active;internal Func<UnitEntityData> actor;internal string preparedLeaf,requestedName;internal int preparedWrites,saveRequests=1,completionEntries=1,completionExits=1;internal bool InSynchronousCallback;internal Game game;internal SaveManager saveManager;internal SaveInfo requestedSave,observedSave;internal List<Exception> errors=new List<Exception>();internal JObject last;private void Safe(Action a){try{a();}catch(Exception e){errors.Add(e);}}private JObject Record(string kind,UnitEntityData actor,SaveInfo save){last=new JObject{["kind"]=kind};return last;}internal static int Id(object x)=>x==null?0:System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(x);private static void Require(bool ok,string reason){if(!ok)throw new InvalidOperationException(reason);}
