internal static class Tests{static int pass,fail;static void Is(bool ok){if(!ok)throw new Exception("assert");}static void Throws(Action a){try{a();}catch(ArgumentException){return;}catch(InvalidOperationException){return;}throw new Exception("not refused");}static void Check(string name,Action a){try{a();pass++;Console.WriteLine("PASS "+name);}catch(Exception e){fail++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
static NativeOrdinaryAcquisitionProbe Ordinary(bool assisted){var a=new UnitEntityData();var p=assisted?NativeOrdinaryAcquisitionProbe.ForAssistedFixture(()=>a):new NativeOrdinaryAcquisitionProbe(()=>a);p.game=new Game();Game.Instance=p.game;p.saveManager=p.game.SaveManager;p.requestedSave=new SaveInfo{Name="Autosave",Type=SaveInfo.SaveType.Auto,IsAutoLevelupSave=true};p.requestedName=p.requestedSave.Name;NativeOrdinaryAcquisitionProbe.active=p;return p;}
static SaveInfo Auto(NativeOrdinaryAcquisitionProbe p)=>new SaveInfo{Name=p.requestedName,FileName=p.preparedLeaf,Type=SaveInfo.SaveType.Auto,IsAutoLevelupSave=false};
static Chunk7ManualSeedSaveProbe Manual(string name,string leaf){var g=new Game();Game.Instance=g;var p=new Chunk7ManualSeedSaveProbe(g,new MountedPersistenceService(),x=>x==null?0:1,()=>{},leaf,name);Chunk7ManualSeedSaveProbe.active=p;return p;}
static int Main(){
Check("ordinary constructor retains Auto1 and assisted factory retains Auto2",()=>{Is(Ordinary(false).preparedLeaf=="Auto_1.zks");Is(Ordinary(true).preparedLeaf=="Auto_2.zks");});
Check("both ordinary constructors refuse absent actor callback",()=>{Throws(()=>new NativeOrdinaryAcquisitionProbe(null));Throws(()=>NativeOrdinaryAcquisitionProbe.ForAssistedFixture(null));});
foreach(var assisted in new[]{false,true}){Check("exact prepared Auto "+assisted,()=>{var p=Ordinary(assisted);var save=Auto(p);NativeOrdinaryAcquisitionProbe.Hooks.PreparedAfter(p.saveManager,save);Is(p.errors.Count==0&&ReferenceEquals(p.observedSave,save)&&(bool)p.last["accepted"]);});foreach(var mode in new[]{"other-leaf","name","same-descriptor","manager","game","callback","unreturned","auto","type","requestflag","duplicate"}){var m=mode;Check("prepared Auto refuses "+assisted+" "+m,()=>{var p=Ordinary(assisted);var save=Auto(p);var manager=p.saveManager;if(m=="other-leaf")save.FileName=assisted?"Auto_1.zks":"Auto_2.zks";if(m=="name")save.Name="foreign";if(m=="same-descriptor")save=p.requestedSave;if(m=="manager")manager=new SaveManager();if(m=="game")Game.Instance=new Game();if(m=="callback")p.InSynchronousCallback=true;if(m=="unreturned")p.completionExits=0;if(m=="auto")save.IsAutoLevelupSave=true;if(m=="type")save.Type=SaveInfo.SaveType.Manual;if(m=="requestflag")p.requestedSave.IsAutoLevelupSave=false;if(m=="duplicate")p.preparedWrites=1;NativeOrdinaryAcquisitionProbe.Hooks.PreparedAfter(manager,save);Is(p.errors.Count==1&&p.observedSave==null&&!(bool)p.last["accepted"]);});}}
foreach(var name in new[]{(string)null,Chunk7AcquiredManualSelection.OutputName,Chunk7AssistedFixtureSelection.OutputName}){var n=name;Check("closed Manual name completes "+(n??"seed"),()=>{var actual=n??Chunk7ManualSeedSelection.OutputName;var leaf="Manual_7_"+actual+".zks";var p=Manual(n,leaf);var request=new SaveInfo{Name=actual,Type=SaveInfo.SaveType.Manual};p.Expect(request);var save=new SaveInfo{Name=actual,FileName=leaf,Type=SaveInfo.SaveType.Manual,GameId=p.game.Player.GameId,Area=p.game.CurrentlyLoadedArea};Chunk7ManualSeedSaveProbe.Hooks.PreparedAfter(p.manager,save);Is(ReferenceEquals(p.expected,request)&&ReferenceEquals(p.prepared,save)&&p.errors.Count==0);});}
foreach(var name in new[]{Chunk7AcquiredManualSelection.OutputName,Chunk7AssistedFixtureSelection.OutputName})foreach(var number in new[]{"0","-1","01","+1","2147483648"," 1",""}){var n=name;var v=number;Check("Manual constructor refuses canonical alias "+n+" "+v,()=>Throws(()=>Manual(n,"Manual_"+v+"_"+n+".zks")));}
Check("Manual constructor refuses cross-name leaf and foreign name",()=>{Throws(()=>Manual(Chunk7AssistedFixtureSelection.OutputName,Chunk7AcquiredManualSelection.NativeOutputLeaf(1)));Throws(()=>Manual(Chunk7AcquiredManualSelection.OutputName,Chunk7AssistedFixtureSelection.ManualLeaf(1)));Throws(()=>Manual("other","Manual_1_other.zks"));});
foreach(var mode in new[]{"expect-name","expect-saved","prepare-name","prepare-leaf","prepare-world","prepare-manager"}){var m=mode;Check("assisted Manual refuses "+m,()=>{var p=Manual(Chunk7AssistedFixtureSelection.OutputName,Chunk7AssistedFixtureSelection.ManualLeaf(3));var r=new SaveInfo{Name=p.nativeName,Type=SaveInfo.SaveType.Manual};if(m=="expect-name")r.Name=Chunk7ManualSeedSelection.OutputName;if(m=="expect-saved")r.IsActuallySaved=true;if(m.StartsWith("expect",StringComparison.Ordinal)){Throws(()=>p.Expect(r));Is(p.expected==null);return;}p.Expect(r);var save=new SaveInfo{Name=p.nativeName,FileName=p.leaf,Type=SaveInfo.SaveType.Manual,GameId=p.game.Player.GameId,Area=p.game.CurrentlyLoadedArea};if(m=="prepare-name")save.Name=Chunk7ManualSeedSelection.OutputName;if(m=="prepare-leaf")save.FileName=Chunk7AssistedFixtureSelection.ManualLeaf(4);if(m=="prepare-world")save.GameId="foreign";Chunk7ManualSeedSaveProbe.Hooks.PreparedAfter(m=="prepare-manager"?new SaveManager():p.manager,save);Is(p.errors.Count==1&&p.prepared==null);});}
Console.WriteLine("TOTAL PASS="+pass+" FAIL="+fail);return fail==0?0:1;}
